use genewars_render::{plant::*,plant_scene::*,terrain::TerrainFadeTable,terrain_modes::MainGlaTable};
use std::{env,fs,io::{BufWriter,Write},path::Path};
#[path="../../rust/crates/genewars-tools/src/plant_scene.rs"] mod snapshot;
fn read_input(p:&str)->Result<Vec<u8>,String>{fs::read(p).map_err(|e|e.to_string())}
fn read(b:&[u8],at:&mut usize)->i32{let v=i32::from_le_bytes(b[*at..*at+4].try_into().unwrap());*at+=4;v}
fn put(out:&mut impl Write,v:usize){out.write_all(&(v as u32).to_le_bytes()).unwrap();}
fn main(){let a:Vec<String>=env::args().collect();let p=Path::new(&a[1]);let resources:Vec<Vec<u8>>=fs::read_to_string(p.join("resources.txt")).unwrap().lines().map(|s|fs::read(s).unwrap()).collect();let frames:Vec<_>=fs::read(p.join("frames.bin")).unwrap().chunks_exact(3).map(|b|PlantFrame::parse_indexed8(&resources[b[0]as usize],b[1],b[2]).unwrap()).collect();let fades=[fs::read(p.join("fade.bin")).unwrap(),(0..16384).map(|i|((i/256)*13+i*7+3)as u8).collect()];let glas=[fs::read(p.join("gla.bin")).unwrap(),(0..65536).map(|i|((i/256)*19+i*7+5)as u8).collect()];let mut out=BufWriter::new(fs::File::create(p.join("results.bin")).unwrap());let b=fs::read(p.join("scenes.bin")).unwrap();let mut at=0;let count=read(&b,&mut at);
 for _ in 0..count{let h:Vec<_>=(0..9).map(|_|read(&b,&mut at)).collect();let[w,height,pitch,prefix]=[h[0]as usize,h[1]as usize,h[2]as usize,h[3]as usize];let minimum=if w==0||height==0{0}else{(height-1)*pitch+w};let extent=(minimum as i64+h[4]as i64).max(0)as usize;let mut dest:Vec<u8>=(0..prefix+extent+3).map(|i|(i*37+h[7]as usize)as u8).collect();let before=dest.clone();let records:Vec<_>=(0..h[8]).map(|_|{let v:Vec<_>=(0..9).map(|_|read(&b,&mut at)).collect();PlantSceneRecord{id:v[1]as u32,frame:&frames[v[0]as usize],origin:[v[2],v[3]],inputs:PlantColorInputs{context_flags_at_16e0c4:v[4]as u8,entity_flags_at_15:v[5]as u8,native_flags_at_2e:v[6]as u8,shade_at_17:v[7]as u8},draw:v[8]!=0}}).collect();let fade=TerrainFadeTable::parse(&fades[h[6]as usize]).unwrap();let gla=MainGlaTable::parse(&glas[h[6]as usize]).unwrap();
  match draw_explicit_family1_scene(&records,&mut dest[prefix..prefix+extent],[w,height],pitch,if h[5]!=0{Some(&fade)}else{None},&gla){Err(e)=>{assert_eq!(dest,before);out.write_all(&[1]).unwrap();let(kind,id)=match e{PlantSceneError::RecordDraw{id,..}=>(2,id),_=>(1,0)};out.write_all(&[kind]).unwrap();out.write_all(&id.to_le_bytes()).unwrap();},Ok(r)=>{out.write_all(&[0]).unwrap();for n in [r.foreground_pixels_written,r.foreground_pixels_clipped,r.shadow_pixels_written,r.shadow_pixels_clipped,r.pixels_written,r.pixels_clipped]{out.write_all(&(n as u64).to_le_bytes()).unwrap();}put(&mut out,r.records.len());for row in r.records{out.write_all(&row.id.to_le_bytes()).unwrap();match row.status{PlantSceneRecordStatus::SkippedByCaller=>out.write_all(&[0]).unwrap(),PlantSceneRecordStatus::Drawn(d)=>{out.write_all(&[1]).unwrap();let route=match d.foreground_route{PlantColorRoute::Direct=>-1i16,PlantColorRoute::Fade{shade}=>shade as i16};out.write_all(&route.to_le_bytes()).unwrap();for n in [d.foreground_pixels_written,d.foreground_pixels_clipped,d.shadow_pixels_written,d.shadow_pixels_clipped]{put(&mut out,n);}}}}}}
  put(&mut out,dest.len());out.write_all(&dest).unwrap();
 }
 assert_eq!(at,b.len());let mut parser_ok=0;let mut parser_bad=0;for path in fs::read_to_string(p.join("snapshots.txt")).unwrap().lines(){let data=fs::read(path).unwrap();if path.contains("invalid-"){assert!(snapshot::Snapshot::parse(&data).is_err(),"{path}");parser_bad+=1;}else{let s=snapshot::Snapshot::parse(&data).unwrap();let fade=TerrainFadeTable::parse(&fades[0]).unwrap();let gla=MainGlaTable::parse(&glas[0]).unwrap();let mut image:Vec<u8>=(0..307200).map(|i|(i*37+11)as u8).collect();let result=s.draw(p.join("slots").to_str().unwrap(),&mut image[128..],&fade,&gla).unwrap();let n=parser_ok;fs::write(p.join(format!("snapshot-result-{n}.json")),result).unwrap();fs::write(p.join(format!("snapshot-frame-{n}.bin")),image).unwrap();parser_ok+=1;}}
 put(&mut out,parser_ok);put(&mut out,parser_bad);out.flush().unwrap();}
